        data: {"result": {"minY": 1.0, "minX": 0.0, "maxY": 15028.0, "series": [{"data": [[100.0, 1.0]], "isOverall": false, "label": "[verificación] POST procesar", "isController": false}, {"data": [[0.0, 7362.0], [100.0, 164.0], [200.0, 4.0]], "isOverall": false, "label": "POST /api/pedidos/procesar", "isController": false}, {"data": [[100.0, 1.0]], "isOverall": false, "label": "[verificación] GET detalle", "isController": false}, {"data": [[0.0, 15028.0]], "isOverall": false, "label": "GET /api/pedidos/detalle/{id}", "isController": false}], "supportsControllersDiscrimination": true, "granularity": 100, "maxX": 200.0, "title": "Response Time Distribution"}},
